```javascript
/**
 * @return {Object}
 */
var createInfiniteObject = function() {
    return new Proxy({}, {
        get(target, prop) {
            // Every property is a function that returns its own name
            return () => prop;
        }
    });
};

/**
 * const obj = createInfiniteObject();
 * obj['abc123'](); // "abc123"
 */
